//! Credits: who made the manager, where to find it, and the open-source
//! crates it is built on.
use super::{Message, Page, State};
use crate::ui_kit::{BadgeKind, badge};
use crate::{design, icons, ui_kit};
use iced::widget::{column, container, image, row, scrollable, space, text};
use iced::{Background, Border, Element, Fill, Length};

mod built_on {
    // Generated by build.rs: (crate, version, licence).
    include!(concat!(env!("OUT_DIR"), "/acknowledgements.rs"));
}

pub(super) const DISCORD_PROFILE: &str = "https://discord.com/users/673624991039881229";
pub(super) const DISCORD_SERVER: &str = "https://discord.gg/evomodded";
pub(super) const REPOSITORY: &str = "https://github.com/corvodl/Evolve-Mod-Manager";
pub(super) const INSTALLER: &str = "https://modded-evolve.com";

/// Only these fixed addresses can be opened from Credits.
pub(super) fn open(url: &str) -> Result<(), String> {
    if ![DISCORD_PROFILE, DISCORD_SERVER, REPOSITORY, INSTALLER].contains(&url) {
        return Err("Credits can only open its own links".into());
    }
    crate::whats_new::open_in_browser(url)
}

const VERSION: &str = env!("CARGO_PKG_VERSION");

fn channel() -> (BadgeKind, &'static str) {
    if VERSION.contains("-nightly") {
        (BadgeKind::Nightly, "Nightly")
    } else if VERSION.contains("-beta") {
        (BadgeKind::Modified, "Beta")
    } else {
        (BadgeKind::Signed, "Stable")
    }
}

/// Crates grouped by what they do for the manager.
fn group(name: &str) -> &'static str {
    match name {
        "iced" | "image" | "similar" => "Interface",
        "wgpu" | "bytemuck" | "bcdec_rs" | "half" => "Graphics",
        "zip" | "quick-xml" | "crc32fast" | "flate2" | "twofish" | "cipher" | "rsa" | "sha2" => {
            "Game files"
        }
        "tokio" | "reqwest" | "sysinfo" | "read-process-memory" | "fs2" | "semver" => {
            "System and network"
        }
        _ => "Data and safety",
    }
}

const GROUPS: [&str; 5] = [
    "Interface",
    "Graphics",
    "Game files",
    "System and network",
    "Data and safety",
];

fn card_style(theme: &iced::Theme) -> container::Style {
    container::Style {
        background: Some(Background::Color(design::surface(theme))),
        border: Border {
            color: design::border(theme),
            width: 1.0,
            radius: design::radius(theme, design::Radius::Large).into(),
        },
        ..container::Style::default()
    }
}

fn hero(state: &State) -> Element<'_, Message> {
    let (kind, channel) = channel();
    let card = container(
        row![
            image(crate::handles::image(include_bytes!(
                "../../../assets/hunt.png"
            )))
            .width(76)
            .height(76),
            column![
                text("Evolve Mod Manager").size(26),
                text("Made by @CorvoDL for the Evolve modding community.")
                    .size(design::BODY)
                    .style(design::muted),
                row![
                    badge(BadgeKind::Neutral, format!("v{VERSION}")),
                    badge(kind, channel),
                ]
                .spacing(6),
            ]
            .spacing(8),
        ]
        .spacing(20)
        .align_y(iced::Center),
    )
    .padding(22)
    .width(Fill)
    .style(card_style);
    ui_kit::spotlight(
        &state.ui,
        "credits-hero".into(),
        card,
        state.preferences.reduce_motion,
    )
}

fn link_tile<'a>(
    state: &'a State,
    icon: iced::widget::svg::Handle,
    title: &'static str,
    detail: &'static str,
    shown: &'static str,
    url: &'static str,
) -> Element<'a, Message> {
    let card = container(
        column![
            row![icons::glyph(icon, 22.0), text(title).size(15)]
                .spacing(10)
                .align_y(iced::Center),
            design::caption(detail),
            row![
                design::button(
                    row![
                        icons::glyph(icons::external(), 14.0),
                        text("Open").size(design::LABEL)
                    ]
                    .spacing(6)
                    .align_y(iced::Center),
                )
                .style(design::secondary)
                .on_press(Message::OpenCreditLink(url)),
                design::mono(shown).width(Fill),
                ui_kit::copy_button(&state.ui, &format!("credits-{title}"), url.to_owned()),
            ]
            .spacing(8)
            .align_y(iced::Center),
        ]
        .spacing(10),
    )
    .padding(16)
    .width(Fill)
    .style(card_style);
    container(ui_kit::spotlight(
        &state.ui,
        format!("credits-link-{title}"),
        card,
        state.preferences.reduce_motion,
    ))
    .width(Length::FillPortion(1))
    .into()
}

fn links(state: &State) -> Element<'_, Message> {
    column![
        row![
            link_tile(
                state,
                icons::user(),
                "@CorvoDL",
                "Creator of the manager. Message on Discord.",
                "discord.com/users/673624991039881229",
                DISCORD_PROFILE,
            ),
            link_tile(
                state,
                icons::discord(),
                "Evolve Modded Discord",
                "The community server: help, releases and announcements.",
                "discord.gg/evomodded",
                DISCORD_SERVER,
            ),
        ]
        .spacing(12),
        row![
            link_tile(
                state,
                icons::code(),
                "Source code",
                "Issues, releases and the full history.",
                "github.com/corvodl/Evolve-Mod-Manager",
                REPOSITORY,
            ),
            link_tile(
                state,
                icons::globe(),
                "Game installer",
                "Install Evolve Stage 2 here before using the manager.",
                "modded-evolve.com",
                INSTALLER,
            ),
        ]
        .spacing(12),
    ]
    .spacing(12)
    .into()
}

fn matching(query: &str) -> Vec<(&'static str, &'static str, &'static str)> {
    built_on::CRATES
        .iter()
        .copied()
        .filter(|(name, _, license)| {
            query.is_empty()
                || name.to_ascii_lowercase().contains(query)
                || license.to_ascii_lowercase().contains(query)
        })
        .collect()
}

fn built_on_section(state: &State) -> Element<'_, Message> {
    let query = state.credits_search.trim().to_ascii_lowercase();
    let crates = matching(&query);
    let mut list = column![
        row![
            design::heading("Built with"),
            space().width(Fill),
            container(crate::forms::search_field(
                "Search crates or licences…",
                &state.credits_search,
                Some(crates.len()),
                Message::CreditsSearch,
            ))
            .width(Length::Fixed(280.0)),
        ]
        .spacing(10)
        .align_y(iced::Center),
        design::caption(
            "Open-source crates this build uses directly, with the licence each is published under."
        ),
    ]
    .spacing(10);
    if built_on::CRATES.is_empty() {
        list = list.push(design::caption(
            "The crate list wasn't available when this build was made.",
        ));
    }
    for name in GROUPS {
        let members = crates
            .iter()
            .filter(|(crate_name, _, _)| group(crate_name) == name)
            .collect::<Vec<_>>();
        if members.is_empty() {
            continue;
        }
        let mut block = column![
            text(name.to_uppercase())
                .size(design::CAPTION)
                .style(design::muted)
        ]
        .spacing(4);
        for (crate_name, version, license) in members {
            block = block.push(
                row![
                    text(*crate_name)
                        .size(design::BODY)
                        .width(Length::FillPortion(3)),
                    design::mono(*version).width(Length::FillPortion(2)),
                    container(badge(
                        BadgeKind::Neutral,
                        if license.is_empty() {
                            "Licence not found"
                        } else {
                            license
                        }
                    ))
                    .width(Length::FillPortion(3)),
                ]
                .spacing(10)
                .align_y(iced::Center),
            );
        }
        list = list.push(block);
    }
    list = list.push(
        column![
            text("ARTWORK").size(design::CAPTION).style(design::muted),
            design::caption(
                "Navigation icons follow Flaticon Uicons, with attribution retained in the original project. The other interface icons are drawn for this app."
            ),
        ]
        .spacing(4),
    );
    container(list)
        .padding(18)
        .width(Fill)
        .style(card_style)
        .into()
}

fn footer(state: &State) -> Element<'_, Message> {
    let client = state
        .client_version
        .as_deref()
        .map(crate::private_pages::short_client_version);
    let info = format!(
        "Evolve Mod Manager v{VERSION}\nGame client {}",
        state.client_version.as_deref().unwrap_or("not detected")
    );
    row![
        design::caption(format!("Evolve Mod Manager v{VERSION}")),
        design::caption(match &client {
            Some(client) => format!("Game client {client}"),
            None => "Game client not detected".to_owned(),
        }),
        space().width(Fill),
        ui_kit::copy_button(&state.ui, "credits-version", info),
        design::button(text("What's New").size(design::LABEL))
            .style(design::secondary)
            .on_press(Message::Navigate(Page::WhatsNew)),
    ]
    .spacing(14)
    .align_y(iced::Center)
    .into()
}

pub(super) fn view(state: &State) -> Element<'_, Message> {
    scrollable(
        column![
            hero(state),
            links(state),
            built_on_section(state),
            footer(state)
        ]
        .spacing(16)
        .padding(iced::Padding {
            top: 4.0,
            right: 14.0,
            bottom: 12.0,
            left: 0.0,
        }),
    )
    .height(Fill)
    .into()
}

#[cfg(test)]
mod tests {
    #[test]
    fn only_the_fixed_links_open() {
        assert!(super::open("https://example.com").is_err());
        assert!(super::open("https://discord.gg/evomodded.example").is_err());
    }

    #[test]
    fn build_lists_the_crates_the_manager_uses() {
        let names = super::built_on::CRATES
            .iter()
            .map(|(name, _, _)| *name)
            .collect::<Vec<_>>();
        assert!(names.contains(&"iced"));
        assert!(names.contains(&"serde"));
        assert!(!names.contains(&"evolve-core"));
        assert!(
            super::built_on::CRATES
                .iter()
                .all(|(_, version, _)| !version.is_empty())
        );
    }
}
